globalCss:
/* Synthwave 全局样式 */

:root {
  --synth-pink: #ff00ff;
  --synth-cyan: #00ffff;
  --synth-purple: #7b68ee;
  --synth-orange: #ff6ec7;
}

/* 霓虹发光 */
.synth-glow {
  text-shadow:
    0 0 10px var(--synth-pink),
    0 0 20px var(--synth-pink),
    0 0 40px var(--synth-pink);
}

/* 网格地板 */
.synth-grid {
  background-image:
    linear-gradient(90deg, rgba(255, 0, 255, 0.3) 1px, transparent 1px),
    linear-gradient(rgba(255, 0, 255, 0.3) 1px, transparent 1px);
  background-size: 60px 30px;
  transform: perspective(500px) rotateX(60deg);
  transform-origin: bottom;
}

/* 日落渐变 */
.synth-sunset {
  background: linear-gradient(
    to bottom,
    #1a0533 0%,
    #4a1942 30%,
    #ff6b6b 60%,
    #feca57 100%
  );
}

/* 扫描线 */
.synth-scanlines::after {
  content: "";
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(
    0deg,
    rgba(0, 0, 0, 0.15) 0px,
    rgba(0, 0, 0, 0.15) 1px,
    transparent 1px,
    transparent 2px
  );
  pointer-events: none;
}
@keyframes synthwave-fade-in {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes synthwave-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.7; }
}

.synthwave-frosted {
  backdrop-filter: blur(12px) saturate(180%);
  -webkit-backdrop-filter: blur(12px) saturate(180%);
  background: rgba(255, 0, 255, 0.08);
}

.synthwave-accent-corner {
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 2rem), calc(100% - 2rem) 100%, 0 100%);
}

.synthwave-animate-in {
  animation: synthwave-fade-in 0.5s ease-out both;
}
